//! This is a test crate to check the code generated by `BuildOptions`
//! in an edition 2024 crate.

#![deny(missing_docs)]
#![deny(warnings)]

/// Crate errors.
pub mod errors {
    include!(concat!(env!("OUT_DIR"), "/errors.rs"));
}

/// Internal errors.
pub mod internal_errors {
    include!(concat!(env!("OUT_DIR"), "/internal_errors.rs"));
}

#[cfg(test)]
mod tests {
    use crate::{errors, internal_errors};

    // Checks that the code of every module of the spec is written to its own
    // file and included: an error of each module displays its spec text.
    #[test]
    fn test_every_module_is_included() {
        let e: errors::Error = errors::kind::TIMEOUT.into();
        assert_eq!(e.to_string(), "Operation timed out.");

        let e: internal_errors::Error = internal_errors::kind::processor::BAD_FILE.into();
        assert_eq!(e.to_string(), "Processor file is malformed or missing.");
    }
}
